print(datetime.datetime.now().isoformat())
for t in d['items']:
 if t['thingId'].startswith('kz.tynys:') and not t.get('attributes',{}).get('_isType'):
  a=t.get('attributes',{}); f={k:v.get('properties',{}).get('value') for k,v in t.get('features',{}).items() if not k.endswith('json')}
  print(t['thingId'],json.dumps({'type':a.get('type'),'parents':a.get('_parents'),'links':a.get('links'),'features':f},ensure_ascii=False))
PY

